static class Algorithms
{
    public static int LinearSearch(int[] values, int target)
    {
        for (int i = 0; i < values.Length; i++)
        {
            if (values[i] == target)
            {
                return i;
            }
        }
        return -1;
    }
}

static class Algorithms
{
    public static int BinarySearch(int[] sorted, int target)
    {
        int low = 0;
        int high = sorted.Length - 1;
        while (low <= high)
        {
            int mid = low + (high - low) / 2;
            if (sorted[mid] == target)
            {
                return mid;
            }
            if (sorted[mid] < target)
            {
                low = mid + 1;
            }
            else
            {
                high = mid - 1;
            }
        }
        return -1;
    }
}

static class Algorithms
{
    public static void BubbleSort(int[] values)
    {
        for (int end = values.Length - 1; end > 0; end--)
        {
            bool swapped = false;
            for (int i = 0; i < end; i++)
            {
                if (values[i] > values[i + 1])
                {
                    (values[i], values[i + 1]) = (values[i + 1], values[i]);
                    swapped = true;
                }
            }
            if (!swapped)
            {
                break;
            }
        }
    }
}

static class Algorithms
{
    public static void SelectionSort(int[] values)
    {
        for (int i = 0; i < values.Length - 1; i++)
        {
            int min = i;
            for (int j = i + 1; j < values.Length; j++)
            {
                if (values[j] < values[min])
                {
                    min = j;
                }
            }
            if (min != i)
            {
                (values[i], values[min]) = (values[min], values[i]);
            }
        }
    }
}

static class Algorithms
{
    public static void InsertionSort(int[] values)
    {
        for (int i = 1; i < values.Length; i++)
        {
            int current = values[i];
            int j = i - 1;
            while (j >= 0 && values[j] > current)
            {
                values[j + 1] = values[j];
                j--;
            }
            values[j + 1] = current;
        }
    }
}

static class Algorithms
{
    public static void MergeSort(int[] values)
    {
        if (values.Length < 2)
        {
            return;
        }
        int mid = values.Length / 2;
        int[] left = values[..mid];
        int[] right = values[mid..];
        MergeSort(left);
        MergeSort(right);
        Merge(values, left, right);
    }

    private static void Merge(int[] target, int[] left, int[] right)
    {
        int i = 0;
        int j = 0;
        int k = 0;
        while (i < left.Length && j < right.Length)
        {
            if (left[i] <= right[j])
            {
                target[k++] = left[i++];
            }
            else
            {
                target[k++] = right[j++];
            }
        }
        while (i < left.Length)
        {
            target[k++] = left[i++];
        }
        while (j < right.Length)
        {
            target[k++] = right[j++];
        }
    }
}

static class Algorithms
{
    public static void QuickSort(int[] values) => QuickSort(values, 0, values.Length - 1);

    private static void QuickSort(int[] values, int low, int high)
    {
        if (low >= high)
        {
            return;
        }
        int pivot = Partition(values, low, high);
        QuickSort(values, low, pivot - 1);
        QuickSort(values, pivot + 1, high);
    }

    private static int Partition(int[] values, int low, int high)
    {
        int pivot = values[high];
        int smaller = low;
        for (int i = low; i < high; i++)
        {
            if (values[i] < pivot)
            {
                (values[smaller], values[i]) = (values[i], values[smaller]);
                smaller++;
            }
        }
        (values[smaller], values[high]) = (values[high], values[smaller]);
        return smaller;
    }
}

static class Algorithms
{
    public static void HeapSort(int[] values)
    {
        int size = values.Length;
        for (int i = size / 2 - 1; i >= 0; i--)
        {
            SiftDown(values, i, size);
        }
        for (int end = size - 1; end > 0; end--)
        {
            (values[0], values[end]) = (values[end], values[0]);
            SiftDown(values, 0, end);
        }
    }

    private static void SiftDown(int[] values, int root, int size)
    {
        while (true)
        {
            int largest = root;
            int left = 2 * root + 1;
            int right = left + 1;
            if (left < size && values[left] > values[largest])
            {
                largest = left;
            }
            if (right < size && values[right] > values[largest])
            {
                largest = right;
            }
            if (largest == root)
            {
                return;
            }
            (values[root], values[largest]) = (values[largest], values[root]);
            root = largest;
        }
    }
}

using System.Collections.Generic;

class Graph
{
    private readonly Dictionary<string, List<string>> _edges = new Dictionary<string, List<string>>();

    public void AddEdge(string from, string to)
    {
        AddNeighbor(from, to);
        AddNeighbor(to, from);
    }

    public List<string> Neighbors(string node)
    {
        if (_edges.ContainsKey(node))
        {
            return _edges[node];
        }
        return new List<string>();
    }

    private void AddNeighbor(string from, string to)
    {
        if (!_edges.ContainsKey(from))
        {
            _edges[from] = new List<string>();
        }
        _edges[from].Add(to);
    }
}

using System.Collections.Generic;

static class Algorithms
{
    public static List<string> BreadthFirst(Graph graph, string start)
    {
        List<string> order = new List<string>();
        HashSet<string> visited = new HashSet<string> { start };
        Queue<string> queue = new Queue<string>();
        queue.Enqueue(start);
        while (queue.Count > 0)
        {
            string node = queue.Dequeue();
            order.Add(node);
            foreach (string next in graph.Neighbors(node))
            {
                if (visited.Add(next))
                {
                    queue.Enqueue(next);
                }
            }
        }
        return order;
    }
}

using System.Collections.Generic;

static class Algorithms
{
    public static List<string> DepthFirst(Graph graph, string start)
    {
        List<string> order = new List<string>();
        HashSet<string> visited = new HashSet<string>();
        Visit(graph, start, visited, order);
        return order;
    }

    private static void Visit(Graph graph, string node, HashSet<string> visited, List<string> order)
    {
        if (!visited.Add(node))
        {
            return;
        }
        order.Add(node);
        foreach (string next in graph.Neighbors(node))
        {
            Visit(graph, next, visited, order);
        }
    }
}

