    public int Weight { get; }
}

class WeightedGraph
{
    private readonly Dictionary<string, List<Edge>> _edges = new Dictionary<string, List<Edge>>();

    public void AddEdge(string from, string to, int weight)
    {
        AddNeighbor(from, new Edge(to, weight));
        AddNeighbor(to, new Edge(from, weight));
    }

    public List<Edge> Neighbors(string node)
    {
        if (_edges.ContainsKey(node))
        {
            return _edges[node];
        }
        return new List<Edge>();
    }

    private void AddNeighbor(string from, Edge edge)
    {
        if (!_edges.ContainsKey(from))
        {
            _edges[from] = new List<Edge>();
        }
        _edges[from].Add(edge);
    }
}

static class Algorithms
{
    public static Dictionary<string, long> Dijkstra(WeightedGraph graph, string start)
    {
        Dictionary<string, long> distances = new Dictionary<string, long> { [start] = 0 };
        HashSet<string> visited = new HashSet<string>();
        while (true)
        {
            string current = start;
            long best = long.MaxValue;
            bool found = false;
            foreach (KeyValuePair<string, long> entry in distances)
            {
                if (!visited.Contains(entry.Key) && entry.Value < best)
                {
                    best = entry.Value;
                    current = entry.Key;
                    found = true;
                }
            }
            if (!found)
            {
                break;
            }
            visited.Add(current);
            foreach (Edge edge in graph.Neighbors(current))
            {
                long candidate = best + edge.Weight;
                if (!distances.TryGetValue(edge.To, out long known) || candidate < known)
                {
                    distances[edge.To] = candidate;
                }
            }
        }
        return distances;
    }
}

